typedef struct {
    int id;
    char* dynamic_data;
} ManagedResource;

// Destructor
void ManagedResource_destroy(ManagedResource* self) {
    if (self->dynamic_data) {
        free(self->dynamic_data);
    }
    self->dynamic_data = NULL;
}

// Custom Copy-Assignment (Deep Copy)
void ManagedResource_copy(ManagedResource* dest, const ManagedResource* src) {
    if (dest == src) return;
    ManagedResource_destroy(dest); // Release destination resources

    dest->id = src->id;
    if (src->dynamic_data) {
        // Using strdup (requires C standard library) for deep copy
        dest->dynamic_data = strdup(src->dynamic_data);
    } else {
        dest->dynamic_data = NULL;
    }
}
